const HIT_SPARK := preload("res://effects/hit_spark.tscn")

func _hit_spark(target: Enemy) -> void:
	if not is_instance_valid(game) or not is_instance_valid(target): return
	var burst := HIT_SPARK.instantiate() as Node3D
	burst.position = game.to_local(target.global_position)
	game.add_child(burst)

func _show_fuel() -> void:
	var on := burn_left > 0.0
	var ratio := LOW_RATIO + (1.0 - LOW_RATIO) * clampf(burn_left / FULL_FIRE, 0.0, 1.0)
	for p in _emitters:
		p.amount_ratio = ratio
		if on and not p.emitting: p.restart()
		elif p.emitting != on: p.emitting = on

params.angle = mix(initial_angle_min, initial_angle_max, rand_from_seed(alt_seed));
params.angular_velocity = mix(angular_velocity_min, angular_velocity_max, rand_from_seed(alt_seed));
params.initial_velocity_multiplier = mix(initial_linear_velocity_min, initial_linear_velocity_max, rand_from_seed(alt_seed));

void process_display_param(inout DisplayParameters parameters, float lifetime) {
	// Compile-time add textures.
	parameters.scale *= texture(scale_curve, vec2(lifetime)).rgb;
	parameters.color *= texture(color_ramp, vec2(lifetime));
	parameters.color = rotate_hue(parameters.color, parameters.hue_rotation);
}

# Self-checks: is the instrument measuring itself?
var sleep_ms := OS.low_processor_usage_mode_sleep_usec / 1000.0
if absf(e.wall - g.wall) <= 2.0 * maxf(e.wall_sd, g.wall_sd) or g.wall < 2.0 * e.wall:
	print("WARNING: the empty scene and the game scene read the same: the script is measuring itself")
	bad = true
else:
	print("CHECK empty (%.4f ms) and game_off (%.4f ms) differ by %.0fx: the instrument sees the scene" % [e.wall, g.wall, g.wall / maxf(e.wall, 1e-6)])
if e.wall > 0.5 * sleep_ms:
	print("WARNING: the empty scene takes %.3f ms, near the %.3f ms low-processor sleep: measuring the sleep (run with --fixed-fps)" % [e.wall, sleep_ms])
	bad = true
else:
	print("CHECK empty frame %.4f ms << %.3f ms sleep: no frame sleep in the timing" % [e.wall, sleep_ms])
